import React, { useState, useEffect } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";

const App = () => {
  const [activePage, setActivePage] = useState("chat");
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [isLoading, setIsLoading] = useState(true);

  // 🔹 Load chat messages from localStorage when the app starts
  useEffect(() => {
    const savedMessages = localStorage.getItem("messages");
    if (savedMessages) {
      setMessages(JSON.parse(savedMessages));
    }
    setIsLoading(false);
  }, []);

  // 🔹 Save messages to localStorage when they update
  useEffect(() => {
    if (!isLoading && messages.length > 0) {
      localStorage.setItem("messages", JSON.stringify(messages));
    }
  }, [messages, isLoading]);

  return (
    <div className="app-container">
      {/* Sidebar Navigation */}
      <Navbar activePage={activePage} setActivePage={setActivePage} />

      {/* Main Content Area */}
      <div className="content">
        {activePage === "chat" && (
          <ChatBox messages={messages} setMessages={setMessages} setLatestQuery={setLatestQuery} />
        )}
        {activePage === "youtube" && <YouTube latestQuery={latestQuery} />}
        {activePage === "wikipedia" && <Wikipedia latestQuery={latestQuery} />}
        {activePage === "test" && <Test messages={messages} latestQuery={latestQuery} />}
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
